  "wealthDetail.property.narrative.inflationAdjustedCost": "Your ₹{purchase} purchase equals roughly ₹{todayEquivalent} in today's money after {years} years at ~{inflation}% compounded inflation — real growth is measured against that, not the original price alone.",
  "wealthDetail.property.narrative.purchaseDerived": "خریداری کی قیمت ریٹ × ایریا سے آتی ہے جو آپ نے درج کی ہے — اگر کل غلط لگتا ہے تو ترمیم پر ٹیپ کریں۔",
  "wealthDetail.property.narrative.realReturnExplain": "Nominal CAGR {cagr}% minus ~{inflation}% inflation ≈ {real}% real return per year — property often looks strong in rupee terms while barely beating inflation after costs.",
  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "لانگ ہولڈز ٹائمنگ کے خطرے کو کم کرتے ہیں لیکن کیپیٹل کو لاک کرتے ہیں - 6-12 ماہ کے اخراجات کو فروخت کے قابل دولت کے طور پر استعمال کرنے سے پہلے کہیں اور مائع رکھیں۔",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "اگر مکمل طور پر کرایہ پر لیا گیا ہے تو، مجموعی کرایہ آپ کی اعلان کردہ ماہانہ آمدنی کا ~{pct}% ہوگا — چیک کریں کہ آیا یہ آپ کے حقیقی یا قابل حصول کرایہ سے میل کھاتا ہے۔",
  "wealthDetail.property.narrative.valueVsIncome": "یہ اثاثہ ~{multiple}× کاغذ پر آپ کی سالانہ آمدنی ہے - ایک بڑا ارتکاز؛ ہنگامی اور تنوع کی منصوبہ بندی کا عنصر۔",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "ایک چھوٹے شہر میں اس قدر پر، خریدار کو تلاش کرنے میں مہینوں لگ سکتے ہیں — حقیقت پسندانہ قیمت اور فوری طور پر دستیاب نقدی کے طور پر پوری قیمت کو شمار کرنے سے گریز کریں۔",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "ٹائر-2 مارکیٹ کے لیے اعلیٰ ٹکٹ — اپنی بیان کردہ قیمت پر فوری لیکویڈیٹی سنبھالنے سے پہلے قریبی رجسٹرڈ سیلز کی تصدیق کریں۔",
  "wealthDetail.property.narrative.targetCagrReality": "یہاں سے 12% CAGR کا پیچھا کرنے میں آج کی رفتار سے ~{years} مزید سال لگیں گے۔ مستقبل کی واپسی معمول پر آسکتی ہے۔",
  "wealthDetail.property.narrative.landHold": "زمین: سب سے کم دیکھ بھال لیکن سب سے سست لیکویڈیٹی — 10+ سال کے افق کے لیے بہترین؛ فہرست میں شامل ہونے سے پہلے بوجھ، زوننگ، اور سڑک کو چوڑا کرنے کی اطلاعات کو چیک کریں۔",
  "wealthDetail.property.narrative.commercialHold": "کمرشل: خالی جگہ اور کرایہ دار کا معیار اتنا ہی اہمیت رکھتا ہے جتنا کہ مقام — دوبارہ اندازہ لگائیں کہ آیا فٹ فال یا لیز کی شرائط کمزور ہیں۔",
  "wealthDetail.property.narrative.residentialHold": "رہائشی: خود استعمال فروخت کرنے کے دباؤ کو کم کرتا ہے۔ اگر کرایہ پر لیا جائے تو کرایہ داروں کے کاروبار اور سوسائٹی کی دیکھ بھال میں اضافے کو ٹریک کریں۔",
  "wealthDetail.property.narrative.verifyTitle": "کسی بھی فروخت سے پہلے: انکمبرنس سرٹیفکیٹ، پراپرٹی ٹیکس کی رسیدیں، اور اتپریورتن کی حیثیت - یہاں تاخیر کاغذی فوائد کو مٹا دیتی ہے۔",
